package com.aura.coffeeshop.common.persistence;

import org.hibernate.annotations.IdGeneratorType;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Primary key = 5 random characters from {@code [0-9A-Za-z]} (e.g. {@code aZ3x9}), generated by
 * {@link ShortIdGenerator}. Use on a {@code String} {@code @Id} field mapped to a {@code varchar(5)} column.
 */
@IdGeneratorType(ShortIdGenerator.class)
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.FIELD, ElementType.METHOD})
public @interface ShortId {
}
